import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../services/api";
import RecentHistory from "../components/RecentHistory";


function getSavedUser() {
  const savedUser = localStorage.getItem("gigora_user");

  if (!savedUser) {
    return null;
  }

  try {
    return JSON.parse(savedUser);
  } catch {
    localStorage.removeItem("gigora_user");
    return null;
  }
}

function DashboardHome() {
  const navigate = useNavigate();
  const [user, setUser] = useState(getSavedUser);
  const [error, setError] = useState("");
  const [stats, setStats] = useState({});

 const [usage, setUsage] = useState({
  requests_used: 0,
  requests_limit: 5,
  remaining: 5,
  plan: "free",
});

useEffect(() => {
  const token =
    localStorage.getItem("gigora_access_token");

  fetch("http://127.0.0.1:8000/api/history/stats", {
    headers: {
      Authorization: `Bearer ${token}`,
    },
  })
    .then((res) => res.json())
    .then((data) => setStats(data));

  fetch("http://127.0.0.1:8000/api/usage", {
    headers: {
      Authorization: `Bearer ${token}`,
    },
  })
    .then((res) => res.json())
    .then((data) => {
  console.log("Usage API:", data);
  setUsage(data);
});
}, []);

  useEffect(() => {
    const fetchUser = async () => {
      const token = localStorage.getItem("gigora_access_token");

      if (!token) {
        navigate("/login");
        return;
      }

      try {
        const response = await api.get("/api/auth/me", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        localStorage.setItem("gigora_user", JSON.stringify(response.data.user));
        setUser(response.data.user);
        setError("");
      } catch (err) {
        localStorage.removeItem("gigora_access_token");
        localStorage.removeItem("gigora_user");
        setError("Your session has expired. Please login again.");
        navigate("/login");
      }
    };

    fetchUser();
  }, [navigate]);
  const loadDashboard = async () => {
  try {
    const token = localStorage.getItem("gigora_access_token");

    const [statsRes, usageRes] = await Promise.all([
      fetch("http://127.0.0.1:8000/api/history/stats", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }),
      fetch("http://127.0.0.1:8000/api/usage", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }),
    ]);

    const statsData = await statsRes.json();
    const usageData = await usageRes.json();

    setStats(statsData);
    setUsage(usageData);
  } catch (err) {
    console.error(err);
  }
};
useEffect(() => {
  loadDashboard();

  const refresh = () => {
    loadDashboard();
  };

  window.addEventListener("dashboard-update", refresh);

  return () => {
    window.removeEventListener("dashboard-update", refresh);
  };
}, []);
 return (

    <div className="home">
      <h1>
  {user?.name ? `Welcome, ${user.name}` : "Welcome"}

  {usage?.plan === "pro" && (
    <span className="pro-badge">PRO</span>
  )}
</h1>
      {error && <p className="auth-error">{error}</p>}

      {/* Statistics Cards */}
      <div className="stats-container">
        <div className="stat-card">
          <h3>Profile Analyses</h3>
          <p>{stats.profile || 0}</p>
        </div>

        <div className="stat-card">
          <h3>Proposals Generated</h3>
          <p>{stats.proposal || 0}</p>
        </div>

        <div className="stat-card">
          <h3>SEO Optimizations</h3>
          <p>{stats.seo || 0}</p>
        </div>
      </div>

      {/* Existing Feature Cards */}
      <div className="cards">
        <div
          className="card"
          onClick={() => navigate("/profile-analyzer")}
        >
          <h3>Profile Analyzer</h3>
          <p>Analyze your freelancer profile.</p>
        </div>

        <div
          className="card"
          onClick={() => navigate("/gig-seo")}
        >
          <h3>Gig SEO</h3>
          <p>Optimize your gig for better ranking.</p>
        </div>

        <div
          className="card"
          onClick={() => navigate("/proposal-generator")}
        >
          <h3>Proposal Generator</h3>
          <p>Generate winning proposals instantly.</p>
        </div>

      </div>
      <RecentHistory />
        </div>

);
}

export default DashboardHome;
